  var s = SH.getCurrentServer();
  if (s === null) { return { ok: false, reason: 'no-server' }; }
  var pl = s.getPlayerList().getPlayers();
  var src = (pl.size() > 0) ? pl.get(0).createCommandSourceStack() : s.createCommandSourceStack();
  var cmd = "/clear @s";
  s.getCommands().performPrefixedCommand(src, cmd);
  return { ok: true, cmd: cmd };
})()

